    /// Moves `name` to `commit` only if it still points at `expected`
    /// (`None`: must not exist).
    pub(crate) fn update_ref(
        &self,
        name: &str,
        commit: &str,
        expected: Option<&str>,
    ) -> Result<()> {
        eyre::ensure!(
            matches!(commit.len(), 40 | 64),
            "unsupported Git object id: {commit}"
        );
        let zero = "0".repeat(commit.len());
        self.git.run(PlumbingCall::new([
            "update-ref",
            name,
            commit,
            expected.unwrap_or(&zero),
        ]))
    }

    /// Deletes a ref if it exists.
    pub(crate) fn delete_ref(&self, name: &str) -> Result<()> {
        if self.ref_oid(name)?.is_some() {
            self.git
                .run(PlumbingCall::new(["update-ref", "-d", name]))?;
        }
        Ok(())
    }

    /// Find all common ancestors without treating Git failures as absence.
    pub(crate) fn merge_bases(&self, local: &str, remote: &str) -> Result<Vec<String>> {
        let output =
            self.git
                .output_unchecked(PlumbingCall::new(["merge-base", "--all", local, remote]))?;
        if output.status.code() == Some(1) {
            return Ok(vec![]);
        }
        if !output.status.success() {
            bail!(
                "cannot determine dotfile Git ancestry: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
    }
    let roots = Roots::current();
    for path in required {
        if !tracked.would_capture(&path)? {
            let display = display_path(&path);
            if roots.branch_path(&path, None).is_some() {
                miseprintln!(
                    "Not enrolled for recreating this setup: {display}. To include it explicitly: mise dot track {}",
                    shell_escape::escape(display.as_str().into())
                );
            } else {
                miseprintln!(
                    "Not portable for setup sharing: {display}. Place this prerequisite under your home or mise config directory before enrolling it."
                );
            }
        }
    }
    Ok(())
}

