    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub applied: Option<super::reconcile::Object>,
    /// The upstream commit `reconciled` came from.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub upstream_commit: Option<String>,
